// @pit: {"label": "Instrument the repro test to see settlement and output timing"}
async ({ shell: { exec }, workspace: { read, edit } }) => {
  const f = "/tmp/pit/test/durable/settled-output.test.ts";
  const r = await read(f, { format: "raw" });
  let c = r.content.replace(`await submission.wait(context).catch(() => undefined);`, `const settled = await submission.wait(context).catch((e: unknown) => ({ status: "threw", e: String(e) }));
      console.log("SETTLED", JSON.stringify(settled).slice(0, 400), Date.now());`);
  c = c.replace(`echo tick; sleep 0.05`, `echo tick; date +%s%3N >> ticks; sleep 0.05`);
  c = c.replace(`    expect(errors.map(String)).toEqual([]);`, `    const { readFile } = await import("node:fs/promises");\n    const ticks = (await readFile(join(cwd, "ticks"), "utf8")).trim().split("\\n");\n    console.log("TICKS", ticks.length, ticks[0], ticks.at(-1), "ERRORS", errors.map(String));\n    expect(errors.map(String)).toEqual([]);`);
  await edit(f, { revision: r.revision, changes: [{ kind: "replaceFile", content: c }] });
  const t = await exec(`cd /tmp/pit && npx vitest run test/durable/settled-output.test.ts 2>&1 | sed 's/\\x1b\\[[0-9;]*m//g' | grep -E 'SETTLED|TICKS|passed|failed|Error' | head -20`, { timeoutMs: 120000 });
  return t.stdout + t.stderr;
}
